fn binary_search(v: &Vec<u64>, k: u64) -> usize {
    let mut lo: usize = 0;
    let mut hi: usize = v.len(); // exclusive upper bound

    while lo < hi {
        let mid = lo + (hi - lo) / 2;
        let val = v[mid];

        if val < k {
            lo = mid + 1;
        } else if val > k {
            hi = mid;
        } else {
            return mid;
        }
    }

    // Under the stated precondition ("k appears at least once"), we must have returned already.
    unreachable!("precondition violated: target k not found in the array");
}